body.script:
import{initializeApp,getApps,getApp}from'https://www.gstatic.com/firebasejs/10.12.2/firebase-app.js';
import{getFirestore,collection,getDocs}from'https://www.gstatic.com/firebasejs/10.12.2/firebase-firestore.js';
const firebaseConfig={apiKey:'AIzaSyAy-bTRi7dwOvhA1RWLjIR-ghNdHhMh9Sk',authDomain:'mod-hub-27202.firebaseapp.com',projectId:'mod-hub-27202',storageBucket:'mod-hub-27202.firebasestorage.app',messagingSenderId:'10194857054',appId:'1:10194857054:web:fa6282fd44bba178b458cf',measurementId:'G-J2PF6MT03Z'};
const grid=document.getElementById('mhGrid'),status=document.getElementById('mhFirebase'),dot=document.getElementById('mhDot'),count=document.getElementById('mhCount'),search=document.getElementById('mhSearch'),category=document.getElementById('mhCategory');let db,mods=[];
function esc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}
function safeUrl(v){const s=String(v||'').trim();return /^https:\/\/\S+$/i.test(s)?s:''}
function title(m){return String(m.nombre||m.title||m.name||'MOD sin nombre')}
function desc(m){return String(m.descripcion||m['descripción']||m.description||'Sin descripción.')}
function cat(m){return String(m.categoria||m['categoría']||m.category||'Otros').trim()}
function img(m){return String(m.imagen||m.image||m.imageUrl||'').trim()}
function dl(m){return safeUrl(m.descarga||m.download||m.downloadUrl||m.downloadURL||m.enlace||m.link)}
function render(){const q=search.value.toLowerCase().trim(),c=category.value;const list=mods.filter(m=>{const t=(title(m)+' '+desc(m)+' '+String(m.autor||m.author||'')+' '+cat(m)).toLowerCase();return(!q||t.includes(q))&&(!c||cat(m)===c)});count.textContent=list.length+' '+(list.length===1?'MOD':'MODs');if(!list.length){grid.innerHTML='<div class="mh-empty">🔎 No se encontraron MODs.</div>';return}grid.innerHTML=list.map(m=>{const im=img(m),link=dl(m),name=title(m);return '<article class="mh-mod"><div class="mh-mod-img">'+(im?'<img src="'+esc(im)+'" alt="'+esc(name)+'" loading="lazy"/>':'🎮 MOD HUB')+'</div><div class="mh-mod-body"><h3>'+esc(name)+'</h3><p>'+esc(desc(m))+'</p><div class="mh-meta">🎮 '+esc(cat(m))+' · 👤 '+esc(m.autor||m.author||'MOD HUB')+'</div>'+(link?'<a class="mh-btn" href="'+esc(link)+'" target="_blank" rel="noopener noreferrer">📥 DESCARGAR</a>':'<span style="color:#718197;font-size:12px">📦 Descarga no configurada</span>')+'</div></article>'}).join('')}
async function load(){try{const app=getApps().length?getApp():initializeApp(firebaseConfig);db=getFirestore(app);const snap=await getDocs(collection(db,'mods'));mods=[];snap.forEach(d=>{const m={id:d.id,...d.data()};if(m.estado!=='borrador'&&m.activa!==false)mods.push(m)});status.textContent='FIREBASE ONLINE';dot.classList.add('on');const cats=[...new Set(mods.map(cat))].sort((a,b)=>a.localeCompare(b,'es'));category.innerHTML='<option value="">Todas las categorías</option>'+cats.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('');render()}catch(e){console.error('MOD HUB FIREBASE:',e);status.textContent='FIREBASE OFFLINE';count.textContent='0 MODs';grid.innerHTML='<div class="mh-empty">⚠️ No se pudieron cargar los MODs. Revisá las reglas de Firestore y la colección mods.</div>'}}
search.addEventListener('input',render);category.addEventListener('change',render);load();setInterval(load,30000);
